// === Tab: mySketch ===
// Reference: Rock Paper Scissors Cellular Automata
// https://softologyblog.wordpress.com/2018/03/23/rock-paper-scissors-cellular-automata/
// https://josephpetitti.com/rps

t=0
m=100
p=[]
colours=['blue','purple','green']

setup=()=> {
  createCanvas(600,600)
  noStroke()
  for(x=m;x--;){
    p[x]=[]
    for(y=m;y--;){
      p[x][y]={
        colour:int((x+y)/2)%3,
        power:10
      }
    }
  }
}

draw=()=> {  
  t++
  for(dir=0;dir<8;dir++){
    n=Array.from(p)
    for(x=m;x--;){
      for(y=m;y--;){   
        [X,Y]=[
          [(x+1)%m,y],
          [(x-1+m)%m,y],
          [x%m,(y-1+m)%m],
          [x%m,(y+1)%m],
          [(x-1+m)%m,(y-1+m)%m],
          [(x+1)%m,(y-1+m)%m],
          [(x-1+m)%m,(y+1)%m],
          [(x+1)%m,(y+1)%m],
        ][(t&dir)%8]

        neighbor=p[X][Y]

        if((neighbor.colour-p[x][y].colour+3)%3==1){
          n[x][y].power=n[x][y].power-1
          if(n[x][y].power==0){
            n[x][y].colour=neighbor.colour
            n[x][y].power=10
          }
        }
      }
    }
    p=n
  }

  loadPixels()
  for(x=m;x--;){
    for(y=m;y--;){
      set(x,y,color(colours[p[x][y].colour]))
    }
  }
  updatePixels()
  copy(0,0,100,100,0,0,width,height)
}
